const motionPreference = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null;
return {
  draw(ctx, s) {
    const { end, height, high, max, pal, monet, dark } = s;
    const time = motionPreference?.matches ? 0 : s.time;
    const sec = monet.enabled ? monet.secondary : pal;
    const g = ctx.createLinearGradient(0, 0, end, 0);
    g.addColorStop(0, pal.deep(dark ? 0.65 : 0.45));
    g.addColorStop(0.65, sec.main(dark ? 0.82 : 0.72));
    g.addColorStop(1, pal.light(0.92));
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, end, height);

    // 顶部细微玻璃高光沿
    const topLine = ctx.createLinearGradient(0, 0, 0, 10);
    topLine.addColorStop(0, "rgba(255,255,255,0.32)");
    topLine.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = topLine;
    ctx.fillRect(0, 0, end, 10);

    // 极缓慢流过的柔和丝光
    const sweepX = ((time * 18) % (end + 90)) - 45;
    const sg = ctx.createLinearGradient(sweepX - 36, 0, sweepX + 36, 0);
    sg.addColorStop(0, "rgba(255,255,255,0)");
    sg.addColorStop(0.5, `rgba(255,255,255,${0.10 + high * 0.08 + max * 0.10})`);
    sg.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = sg;
    ctx.fillRect(0, 0, end, height);
  }
};
